    adcs_quat_t q_hat;
    adcs_quat_t dq;
    adcs_quat_t next;
    double theta;
    double half_angle;
    double norm_w;
    double s;

    /* 1. Null check */
    if ((q == NULL) || (w == NULL) || (out == NULL)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_NULL;
    }

    /* 2. Finite and Range check */
    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    /* 3. Normalize input quaternion */
    if (adcs_quat_normalize(q, &q_hat) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    /* 4. Calculate theta */
    norm_w = adcs_vec3_norm(w);
    theta = norm_w * dt;

    /* 5. Construct dq */
    if (theta <= ADCS_EPS_NORM) {
        /* Small angle approximation: cos(theta/2) ~ 1, sin(theta/2)/||w|| ~ dt/2 */
        dq.w = 1.0;
        dq.x = 0.5 * w->x * dt;
        dq.y = 0.5 * w->y * dt;
        dq.z = 0.5 * w->z * dt;
    } else {
        half_angle = 0.5 * theta;
        s = sin(half_angle) / norm_w;
        dq.w = cos(half_angle);
        dq.x = s * w->x;
        dq.y = s * w->y;
        dq.z = s * w->z;
    }

    /* 6. Propagate: out = canonicalize(normalize(dq * q_hat)) */
    next = adcs_quat_multiply(&dq, &q_hat);

    /* 7. Normalize and Canonicalize output */
    if (adcs_quat_normalize(&next, out) != ADCS_OK) {
        /* Theoretical degenerate case for unit quaternion product is unlikely but handled per contract */
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    /* Canonicalize w >= 0 */
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }

    return ADCS_OK;
}

